// oxtty/xterm: the Rust front end (xterm_web.js, generated by wasm-bindgen from crates/oxtty-web) over the oxtty
// engine (index.js). `init()` loads both WebAssembly modules; everything else is the generated binding.
import { init as initEngine } from './index.js';
import initFrontEnd, { Terminal as FrontEndTerminal } from './xterm_web.js';

export * from './xterm_web.js';

let ready = false;

/** The generated `Terminal`, with a clear error before `init()` has finished (the glue fails with a TypeError). */
export class Terminal extends FrontEndTerminal {
  constructor(options) {
    if (!ready) throw new Error('oxtty/xterm: await init() before new Terminal()');
    super(options);
  }
}

/** Loads the engine and the front end once. Sources default to the files next to this module. */
export async function init(engine, frontEnd) {
  await Promise.all([initEngine(engine), initFrontEnd({ module_or_path: frontEnd ?? (await defaultFrontEnd()) })]);
  ready = true;
}

// Node cannot fetch file: URLs; read the file there, like index.js does for the engine.
async function defaultFrontEnd() {
  const url = new URL('./xterm_web_bg.wasm', import.meta.url);
  if (url.protocol !== 'file:') return url;
  // Keep the name in a variable so browser bundlers do not follow the node: module.
  const fsModule = 'node:fs/promises';
  const { readFile } = await import(/* @vite-ignore */ /* webpackIgnore: true */ fsModule);
  return readFile(url);
}
